import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isId(v: unknown): boolean {
  if (typeof v !== 'number' && typeof v !== 'string') {
    return false;
  }
  if (String(v).trim() === '') {
    return false;
  }
  return Number.isInteger(Number(v)) && Number(v) > 0;
}

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

@Controller('api/v1')
export class FnSfr00104Controller {
  @Patch('/rfid-tags/:rfidTagId')
  async linkRfidTag(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const rfidTagId = req.params['rfidTagId'];
    if (!isId(rfidTagId)) {
      throw invalid('RFID 태그 ID가 올바르지 않습니다.');
    }
    if (!isId(data['fixedAssetId'])) {
      throw invalid('고정자산을 선택해 주세요.');
    }
    return transaction(async (db) => {
      const tags = await db.query(
        'SELECT rfid_tag_id AS "rfidTagId", fixed_asset_id AS "fixedAssetId" FROM rfid_tag WHERE rfid_tag_id = CAST(:rfidTagId AS bigint)',
        { rfidTagId },
      );
      if (tags.length === 0) {
        throw new ApiError(404, 'RFID_TAG_NOT_FOUND', 'RFID 태그를 찾을 수 없습니다.');
      }
      const assets = await db.query(
        'SELECT fixed_asset_id AS "fixedAssetId" FROM fixed_asset WHERE fixed_asset_id = CAST(:fixedAssetId AS bigint)',
        { fixedAssetId: data['fixedAssetId'] },
      );
      if (assets.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '고정자산을 찾을 수 없습니다.');
      }
      const current = tags[0]['fixedAssetId'];
      if (current !== null && current !== undefined && Number(current) !== Number(data['fixedAssetId'])) {
        throw new ApiError(409, 'RFID_TAG_ALREADY_LINKED', '이미 다른 고정자산에 연결된 태그입니다.');
      }
      const rows = await db.query(
        'UPDATE rfid_tag SET fixed_asset_id = CAST(:fixedAssetId AS bigint), updated_at = now() WHERE rfid_tag_id = CAST(:rfidTagId AS bigint) RETURNING rfid_tag_id AS "rfidTagId", fixed_asset_id AS "fixedAssetId", tag_value AS "tagValue"',
        { rfidTagId, fixedAssetId: data['fixedAssetId'] },
      );
      return rows[0];
    });
  }

  @Post('/asset-scan-logs')
  @HttpCode(200)
  async createAssetScanLog(@Req() req: Request) {
    const user = currentUser(req);
    user.require('로그인 사용자');
    const data = checks.inputOf(req.body);
    if (!isId(data['rfidReaderId'])) {
      throw invalid('RFID 리더기를 선택해 주세요.');
    }
    const tagValue = data['tagValue'];
    if (typeof tagValue !== 'string' || tagValue.trim() === '' || tagValue.length > 100) {
      throw invalid('태그 값은 1~100자로 입력해 주세요.');
    }
    const scannedAt = data['scannedAt'];
    if (typeof scannedAt !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}.*$/.test(scannedAt)) {
      throw invalid('인식일시 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const readers = await db.query(
        'SELECT rfid_reader_id FROM rfid_reader WHERE rfid_reader_id = CAST(:rfidReaderId AS bigint)',
        { rfidReaderId: data['rfidReaderId'] },
      );
      if (readers.length === 0) {
        throw new ApiError(404, 'RFID_READER_NOT_FOUND', '등록되지 않은 리더기입니다.');
      }
      const tags = await db.query(
        'SELECT rfid_tag_id AS "rfidTagId", fixed_asset_id AS "fixedAssetId" FROM rfid_tag WHERE tag_value = :tagValue',
        { tagValue },
      );
      const matched = tags.length > 0 && tags[0]['fixedAssetId'] !== null && tags[0]['fixedAssetId'] !== undefined;
      const rfidTagId = matched ? tags[0]['rfidTagId'] : null;
      const fixedAssetId = matched ? tags[0]['fixedAssetId'] : null;
      const matchResult = matched ? 'MATCHED' : 'UNMATCHED';
      const rows = await db.query(
        'INSERT INTO asset_scan_log (rfid_reader_id, rfid_tag_id, fixed_asset_id, tag_value, scanned_at, match_result, created_at, updated_at) VALUES (CAST(:rfidReaderId AS bigint), CAST(:rfidTagId AS bigint), CAST(:fixedAssetId AS bigint), :tagValue, CAST(:scannedAt AS timestamptz), :matchResult, now(), now()) RETURNING asset_scan_log_id AS "assetScanLogId", fixed_asset_id AS "fixedAssetId", match_result AS "matchResult"',
        { rfidReaderId: data['rfidReaderId'], rfidTagId, fixedAssetId, tagValue, scannedAt, matchResult },
      );
      return rows[0];
    });
  }

  @Get('/asset-scan-logs')
  async listAssetScanLogs(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const query = checks.queryOf(req.query);
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0) {
      throw invalid('page가 올바르지 않습니다.');
    }
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw invalid('size가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, MAX_SIZE);
    const page = pageRaw;
    const hasMatch = query['matchResult'] !== undefined && query['matchResult'] !== '';
    if (hasMatch && query['matchResult'] !== 'MATCHED' && query['matchResult'] !== 'UNMATCHED') {
      throw invalid('매칭 결과가 올바르지 않습니다.');
    }
    const hasAsset = query['fixedAssetId'] !== undefined && query['fixedAssetId'] !== '';
    if (hasAsset && !isId(query['fixedAssetId'])) {
      throw invalid('고정자산 ID가 올바르지 않습니다.');
    }
    const params = {
      matchResult: hasMatch ? String(query['matchResult']) : null,
      fixedAssetId: hasAsset ? String(query['fixedAssetId']) : null,
      size,
      offset: page * size,
    };
    const where = 'WHERE (CAST(:matchResult AS varchar) IS NULL OR match_result = CAST(:matchResult AS varchar)) AND (CAST(:fixedAssetId AS bigint) IS NULL OR fixed_asset_id = CAST(:fixedAssetId AS bigint))';
    return transaction(async (db) => {
      const countRows = await db.query(
        'SELECT COUNT(*) AS "total" FROM asset_scan_log ' + where,
        { matchResult: params.matchResult, fixedAssetId: params.fixedAssetId },
      );
      const items = await db.query(
        'SELECT asset_scan_log_id AS "assetScanLogId", fixed_asset_id AS "fixedAssetId", tag_value AS "tagValue", scanned_at AS "scannedAt", match_result AS "matchResult", rfid_reader_id AS "rfidReaderId" FROM asset_scan_log ' + where + ' ORDER BY scanned_at DESC, asset_scan_log_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        params,
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }
}

