import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Form, LookupSelect, Pager, Pairs, RefName, Select, TextInput, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 10;

export default function FnSfr00104Page({ role, notify }: PageProps) {
  const [matchResult, setMatchResult] = useState('');
  const [fixedAssetId, setFixedAssetId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<'' | 'scan' | 'link'>('');
  const [detail, setDetail] = useState<Row | null>(null);
  const [readerId, setReaderId] = useState<number | string>('');
  const [tagValue, setTagValue] = useState('');
  const [scannedAt, setScannedAt] = useState('');
  const [tagId, setTagId] = useState<number | string>('');
  const [assetId, setAssetId] = useState<number | string>('');

  const list = useData<Page>(
    () => call<Page>('GET', '/asset-scan-logs', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const all = useData<Page>(() => call<Page>('GET', '/asset-scan-logs', role, undefined, { page: 0, size: 1 }), [role]);
  const matched = useData<Page>(() => call<Page>('GET', '/asset-scan-logs', role, undefined, { matchResult: 'MATCHED', page: 0, size: 1 }), [role]);
  const unmatched = useData<Page>(() => call<Page>('GET', '/asset-scan-logs', role, undefined, { matchResult: 'UNMATCHED', page: 0, size: 5 }), [role]);

  function reloadAll() {
    list.reload();
    all.reload();
    matched.reload();
    unmatched.reload();
  }

  function search() {
    setPage(0);
    setApplied({ matchResult, fixedAssetId });
  }

  function reset() {
    setMatchResult('');
    setFixedAssetId('');
    setPage(0);
    setApplied({});
  }

  function close() {
    setMode('');
    setDetail(null);
  }

  async function submitScan() {
    if (readerId === '' || tagValue.trim() === '' || scannedAt.trim() === '') {
      throw new Error('리더기, 태그 값, 인식일시를 모두 입력해 주세요.');
    }
    const res = await call('POST', '/asset-scan-logs', role, { rfidReaderId: readerId, tagValue: tagValue.trim(), scannedAt: scannedAt.trim() });
    notify(res['matchResult'] === 'MATCHED' ? '자산이 인식되었습니다.' : '미매칭 태그로 기록했습니다.');
    setReaderId('');
    setTagValue('');
    setScannedAt('');
    close();
    reloadAll();
  }

  async function submitLink() {
    if (tagId === '' || assetId === '') {
      throw new Error('RFID 태그와 고정자산을 선택해 주세요.');
    }
    await call('PATCH', '/rfid-tags/' + tagId, role, { fixedAssetId: assetId });
    notify('RFID 태그를 고정자산에 연결했습니다.');
    setTagId('');
    setAssetId('');
    close();
    reloadAll();
  }

  const rows = list.data ? list.data.items : [];
  const pending = unmatched.data ? unmatched.data.items : [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>인식 현황</h2>
        <Tiles
          items={[
            ['전체 인식', all.data ? all.data.total : 0],
            ['매칭', matched.data ? matched.data.total : 0],
            ['미매칭', unmatched.data ? unmatched.data.total : 0],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>인식 결과</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="매칭 결과">
            <Select value={matchResult} onChange={setMatchResult} options={[['MATCHED', '매칭'], ['UNMATCHED', '미매칭']]} placeholder="전체" />
          </Field>
          <Field label="고정자산 ID">
            <LookupSelect table="fixed_asset" role={role} value={fixedAssetId} onChange={setFixedAssetId} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : 0}>
          <button onClick={() => setMode('link')}>태그 연결</button>
          <button onClick={() => setMode('scan')}>인식 결과 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="인식 이력이 없습니다."
          columns={[
            { key: 'scannedAt', label: '인식일시', render: (r) => <DateText value={r['scannedAt']} time /> },
            { key: 'tagValue', label: '태그 값' },
            { key: 'fixedAssetId', label: '고정자산 ID', render: (r) => <RefName table="fixed_asset" role={role} value={r['fixedAssetId']} /> },
            { key: 'rfidReaderId', label: 'RFID 리더기 ID', render: (r) => <RefName table="rfid_reader" role={role} value={r['rfidReaderId']} /> },
            { key: 'matchResult', label: '매칭 결과', render: (r) => <Badge value={r['matchResult']} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data ? list.data.total : 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>미매칭 태그</h2>
        <DataTable
          rows={pending}
          onRowClick={(row) => setDetail(row)}
          empty="미매칭 태그가 없습니다."
          columns={[
            { key: 'tagValue', label: '태그 값' },
            { key: 'scannedAt', label: '인식일시', render: (r) => <DateText value={r['scannedAt']} time /> },
          ]}
        />
      </section>
      {mode === 'scan' ? (
        <Drawer title="인식 결과 등록" onClose={close}>
          <Form onSubmit={submitScan} submit="등록">
            <Field label="RFID 리더기 ID" required>
              <LookupSelect table="rfid_reader" role={role} value={readerId} onChange={setReaderId} />
            </Field>
            <Field label="태그 값" required>
              <TextInput value={tagValue} onChange={setTagValue} />
            </Field>
            <Field label="인식일시" required hint="예: 2024-05-01T09:30:00+09:00">
              <TextInput value={scannedAt} onChange={setScannedAt} placeholder="YYYY-MM-DDTHH:mm:ss+09:00" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {mode === 'link' ? (
        <Drawer title="RFID 태그 연결" onClose={close}>
          <Form onSubmit={submitLink} submit="연결">
            <Field label="RFID 태그 ID" required>
              <LookupSelect table="rfid_tag" role={role} value={tagId} onChange={setTagId} />
            </Field>
            <Field label="고정자산" required>
              <LookupSelect table="fixed_asset" role={role} value={assetId} onChange={setAssetId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {detail ? (
        <Drawer title="인식 상세" onClose={close}>
          <Pairs
            items={[
              ['자산 태그 인식 이력 ID', String(detail['assetScanLogId'])],
              ['인식일시', <DateText value={detail['scannedAt']} time />],
              ['태그 값', String(detail['tagValue'])],
              ['고정자산 ID', <RefName table="fixed_asset" role={role} value={detail['fixedAssetId']} />],
              ['RFID 리더기 ID', <RefName table="rfid_reader" role={role} value={detail['rfidReaderId']} />],
              ['매칭 결과', <Badge value={detail['matchResult']} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
